From a2cafdfd8cf5ad8adda6c0ce44a59f46431edf02 Mon Sep 17 00:00:00 2001
From: Jean-Jacques Hiblot <jjhiblot@ti.com>
Date: Mon, 23 Sep 2019 12:02:50 +0200
Subject: [PATCH] leds: tlc591xx: update the maximum brightness

The TLC chips actually offer 257 levels:
- 0: led OFF
- 1-255: Led dimmed is using a PWM. The duty cycle range from 0.4% to 99.6%
- 256: led fully ON

Fixes: e370d010a5fe ("leds: tlc591xx: Driver for the TI 8/16 Channel i2c LED driver")
Signed-off-by: Jean-Jacques Hiblot <jjhiblot@ti.com>
Signed-off-by: Pavel Machek <pavel@ucw.cz>

diff --git a/drivers/leds/leds-tlc591xx.c b/drivers/leds/leds-tlc591xx.c
index 8eadb673dc2e..a8911ebd30e5 100644
--- a/drivers/leds/leds-tlc591xx.c
+++ b/drivers/leds/leds-tlc591xx.c
@@ -13,6 +13,7 @@
 #include <linux/slab.h>

 #define TLC591XX_MAX_LEDS	16
+#define TLC591XX_MAX_BRIGHTNESS	256

 #define TLC591XX_REG_MODE1	0x00
 #define MODE1_RESPON_ADDR_MASK	0xF0
@@ -112,11 +113,11 @@ tlc591xx_brightness_set(struct led_classdev *led_cdev,
 	struct tlc591xx_priv *priv = led->priv;
 	int err;

-	switch (brightness) {
+	switch ((int)brightness) {
 	case 0:
 		err = tlc591xx_set_ledout(priv, led, LEDOUT_OFF);
 		break;
-	case LED_FULL:
+	case TLC591XX_MAX_BRIGHTNESS:
 		err = tlc591xx_set_ledout(priv, led, LEDOUT_ON);
 		break;
 	default:
@@ -209,7 +210,7 @@ tlc591xx_probe(struct i2c_client *client,
 		led->priv = priv;
 		led->led_no = reg;
 		led->ldev.brightness_set_blocking = tlc591xx_brightness_set;
-		led->ldev.max_brightness = LED_FULL;
+		led->ldev.max_brightness = TLC591XX_MAX_BRIGHTNESS;
 		err = devm_led_classdev_register_ext(dev, &led->ldev,
 						     &init_data);
 		if (err < 0) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect definition of the maximum brightness level for the TLC591xx LED driver. The previous implementation used a constant that did not account for the full range of brightness levels provided by the TLC chips, which actually support 257 levels (0-256). This led to potential misrepresentation of the LED's brightness capabilities, as the driver could not properly handle the maximum brightness setting.

        Commit message:
        leds: tlc591xx: update the maximum brightness

The TLC chips actually offer 257 levels:
- 0: led OFF
- 1-255: Led dimmed is using a PWM. The duty cycle range from 0.4% to 99.6%
- 256: led fully ON

Fixes: e370d010a5fe ("leds: tlc591xx: Driver for the TI 8/16 Channel i2c LED driver")
Signed-off-by: Jean-Jacques Hiblot <jjhiblot@ti.com>
Signed-off-by: Pavel Machek <pavel@ucw.cz>  

        Patch:

 #define TLC591XX_MAX_LEDS	16
+#define TLC591XX_MAX_BRIGHTNESS	256

 #define TLC591XX_REG_MODE1	0x00

 static int
 tlc591xx_brightness_set(struct led_classdev *led_cdev,
 			enum led_brightness brightness)
 {
 	struct tlc591xx_led *led = ldev_to_led(led_cdev);
 	struct tlc591xx_priv *priv = led->priv;
 	int err;

-	switch (brightness) {
+	switch ((int)brightness) {
 	case 0:
 		err = tlc591xx_set_ledout(priv, led, LEDOUT_OFF);
 		break;
-	case LED_FULL:
+	case TLC591XX_MAX_BRIGHTNESS:
 		err = tlc591xx_set_ledout(priv, led, LEDOUT_ON);
 		break;
 	default:
 		err = tlc591xx_set_ledout(priv, led, LEDOUT_DIM);
 		if (!err)
 			err = tlc591xx_set_pwm(priv, led, brightness);
 	}

 	return err;
 }


 static int
 tlc591xx_probe(struct i2c_client *client,
 	       const struct i2c_device_id *id)
 {
 	struct device_node *np = client->dev.of_node, *child;
 	struct device *dev = &client->dev;
 	const struct of_device_id *match;
 	const struct tlc591xx *tlc591xx;
 	struct tlc591xx_priv *priv;
 	int err, count, reg;

 	match = of_match_device(of_tlc591xx_leds_match, dev);
 	if (!match)
 		return -ENODEV;

 	tlc591xx = match->data;
 	if (!np)
 		return -ENODEV;

 	count = of_get_child_count(np);
 	if (!count || count > tlc591xx->max_leds)
 		return -EINVAL;

 	priv = devm_kzalloc(dev, sizeof(*priv), GFP_KERNEL);
 	if (!priv)
 		return -ENOMEM;

 	priv->regmap = devm_regmap_init_i2c(client, &tlc591xx_regmap);
 	if (IS_ERR(priv->regmap)) {
 		err = PTR_ERR(priv->regmap);
 		dev_err(dev, "Failed to allocate register map: %d\n", err);
 		return err;
 	}
 	priv->reg_ledout_offset = tlc591xx->reg_ledout_offset;

 	i2c_set_clientdata(client, priv);

 	err = tlc591xx_set_mode(priv->regmap, MODE2_DIM);
 	if (err < 0)
 		return err;

 	for_each_child_of_node(np, child) {
 		struct tlc591xx_led *led;
 		struct led_init_data init_data = {};

 		init_data.fwnode = of_fwnode_handle(child);

 		err = of_property_read_u32(child, "reg", &reg);
 		if (err) {
 			of_node_put(child);
 			return err;
 		}
 		if (reg < 0 || reg >= tlc591xx->max_leds ||
 		    priv->leds[reg].active) {
 			of_node_put(child);
 			return -EINVAL;
 		}
 		led = &priv->leds[reg];

 		led->active = true;
 		led->ldev.default_trigger =
 			of_get_property(child, "linux,default-trigger", NULL);

 		led->priv = priv;
 		led->led_no = reg;
 		led->ldev.brightness_set_blocking = tlc591xx_brightness_set;
-		led->ldev.max_brightness = LED_FULL;
+		led->ldev.max_brightness = TLC591XX_MAX_BRIGHTNESS;
 		err = devm_led_classdev_register_ext(dev, &led->ldev,
 						     &init_data);
 		if (err < 0) {
 			dev_err(dev, "couldn't register LED %s\n",
 				led->ldev.name);
 			return err;
 		}
 	}
 	return 0;
 }



